import{_ as l,a0 as d,w as p,s as r,I as i,x as t,a1 as n,A as o,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"關機時間太長的調查和解決的方法 | LCTT x X-CMD","titleTemplate":false,"description":"關機時間太長的調查和解決的方法 | LCTT (202009) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"關機時間太長的調查和解決的方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"關機時間太長的調查和解決的方法 | LCTT (202009) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202009/20200912 Shutdown Taking Too Long- Here-s How to Investigate and Fix Long Shutdown Time in Linux","title":"關機時間太長的調查和解決的方法","tag":"202009","desc":""},"relativePath":"202009/20200912 Shutdown Taking Too Long- Here-s How to Investigate and Fix Long Shutdown Time in Linux.md","filePath":"[post].md"}'),u={name:"202009/20200912 Shutdown Taking Too Long- Here-s How to Investigate and Fix Long Shutdown Time in Linux.md"};function g(h,s,k,m,b,f){const e=d("Link");return p(),r("div",null,[s[27]||(s[27]=i("h1",{id:"關機時間太長的調查和解決的方法",tabindex:"-1"},[t("關機時間太長的調查和解決的方法 "),i("a",{class:"header-anchor",href:"#關機時間太長的調查和解決的方法","aria-label":"Permalink to “關機時間太長的調查和解決的方法”"},"​")],-1)),s[28]||(s[28]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202009/20/233812o1kd114jzq11lq1l.jpg",alt:""})],-1)),s[29]||(s[29]=i("blockquote",null,[i("p",null,"你的 Linux 系統關機時間太長麼？以下是你可以採取的步驟，來找出導致延遲關機的原因並解決這個問題。")],-1)),i("p",null,[s[1]||(s[1]=t("我希望你對 ",-1)),n(e,{href:"https://linuxhandbook.com/sigterm-vs-sigkill/"},{default:o(()=>[...s[0]||(s[0]=[t("sigterm 和 sigkill",-1)])]),_:1}),s[2]||(s[2]=t(" 的概念有一點熟悉。",-1))]),i("p",null,[s[4]||(s[4]=t("當你",-1)),n(e,{href:"https://itsfoss.com/schedule-shutdown-ubuntu/"},{default:o(()=>[...s[3]||(s[3]=[t("關閉 Linux 系統",-1)])]),_:1}),s[5]||(s[5]=t("時，它會發送終止信號（sigterm），並禮貌地要求正在運行的進程停止。有些進程不符合該行為，它們會忽略終止信號並繼續運行。",-1))]),s[30]||(s[30]=a('<p>這可能會導致關機過程的延遲，因為你的系統會在一個預定義的時間段內等待運行的進程停止。在這個時間段之後，它會發送 <code>kill</code> 信號來強制停止所有剩餘的運行進程並關閉系統。</p><p>事實上，在某些情況下，你會在黑屏上看到一個類似 “a stop job is running” 的信息。</p><p>如果你的系統關閉時間太長，你可以做以下工作：</p><ul><li>檢查哪個進程/服務耗時過長，以及你是否能刪除或重新配置它，使其正常運行。</li><li>更改系統強制停止運行進程前的默認等待時間。（快速而不優雅的方式）</li></ul><p>我的操作系統是使用 systemd 的 Ubuntu。這裏的命令和步驟適用於任何使用 systemd 的 Linux 發行版（大多數發行版都是這樣）。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/09/troubleshoot-long-shutdown-linux.gif?resize=800%2C450&amp;ssl=1" alt=""></p><h3 id="檢查哪些進程會導致-linux-的長時間關機" tabindex="-1">檢查哪些進程會導致 Linux 的長時間關機 <a class="header-anchor" href="#檢查哪些進程會導致-linux-的長時間關機" aria-label="Permalink to “檢查哪些進程會導致 Linux 的長時間關機”">​</a></h3><p>如果你想找出問題所在，你應該檢查上次關機時發生了什麼。使用這個命令來獲得“我知道你上個會話做了什麼”（I Know What You Did Last Summer 的雙關語）的力量。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>journalctl -rb -1</span></span></code></pre></div>',9)),i("p",null,[n(e,{href:"https://linuxhandbook.com/journalctl-command/"},{default:o(()=>[...s[6]||(s[6]=[t("journalctl 命令",-1)])]),_:1}),s[7]||(s[7]=t("能讓你讀取系統日誌。使用選項 ",-1)),s[8]||(s[8]=i("code",null,"-b -1",-1)),s[9]||(s[9]=t(" 可以過濾最後一次啓動會話的日誌。使用選項 ",-1)),s[10]||(s[10]=i("code",null,"-r",-1)),s[11]||(s[11]=t(" 時，日誌將按時間倒序顯示。",-1))]),s[31]||(s[31]=a('<p>換句話説，<code>journalctl -rb -1</code> 命令將顯示最後一次關閉 Linux 系統之前的系統日誌。這裏就是你需要分析 Linux 系統長時間關機問題的地方。</p><h4 id="沒有-journal-日誌-下面是你應該做的。" tabindex="-1">沒有 journal 日誌？下面是你應該做的。 <a class="header-anchor" href="#沒有-journal-日誌-下面是你應該做的。" aria-label="Permalink to “沒有 journal 日誌？下面是你應該做的。”">​</a></h4><p>如果沒有 journal 日誌，請確認你的發行版是否使用 systemd。</p><p>即使在一些使用 systemd 的 Linux 發行版上，journal 日誌也沒有被默認激活。</p><p>請確認 <code>/var/log/journal</code> 是否存在。如果不存在，請創建它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mkdir /var/log/journal</span></span></code></pre></div><p>你還應該檢查 <code>/etc/systemd/journald.conf</code> 文件的內容，並確保 <code>Storage</code> 的值被設置為自動（<code>auto</code>）或持久（<code>persistent</code>）。</p><p>你是否在日誌中發現可疑的東西？是否有一個進程/服務拒絕停止？如果是，調查一下是否可以在沒有副作用的情況下刪除它，或者是否可以重新配置它。請不要在這裏盲目地去刪除東西。你應該對這個進程有所瞭解。</p><h3 id="通過減少默認停止超時來加快-linux-中的關機速度-快速修復" tabindex="-1">通過減少默認停止超時來加快 Linux 中的關機速度（快速修復） <a class="header-anchor" href="#通過減少默認停止超時來加快-linux-中的關機速度-快速修復" aria-label="Permalink to “通過減少默認停止超時來加快 Linux 中的關機速度（快速修復）”">​</a></h3><p>關機的默認等待時間通常設置為 90 秒。在這個時間之後，你的系統會嘗試強制停止服務。</p><p>如果你想讓你的 Linux 系統快速關閉，你可以改變這個等待時間。</p><p>你可以在位於 <code>/etc/systemd/system.conf</code> 的配置文件中找到所有的 systemd 設置。這個文件中應該有很多以 <code>#</code> 開頭的行。它們代表了文件中各條目的默認值。</p><p>在開始之前，最好先複製一份原始文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo cp /etc/systemd/system.conf /etc/systemd/system.conf.orig</span></span></code></pre></div><p>在這裏尋找 <code>DefaultTimeoutStopSec</code>。它可能被設置為 90 秒。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#DefaultTimeoutStopSec=90s</span></span></code></pre></div><p>你得把這個值改成更方便的，比如 5 秒或 10 秒。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DefaultTimeoutStopSec=5s</span></span></code></pre></div><p>如果你不知道如何在終端中編輯配置文件，可以使用這個命令在系統默認的文本編輯器（如 Gedit）中打開文件進行編輯：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo xdg-open /etc/systemd/system.conf</span></span></code></pre></div><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/09/change-shutdown-time-settings-ubuntu.png?resize=797%2C322&amp;ssl=1" alt="Change Shutdown Time Settings Ubuntu"></p><p>不要忘記<strong>刪除 DefaultTimeoutStopSec 前的 <code>#</code> 號</strong>。保存文件並重啓系統。</p><p>這將幫助你減少 Linux 系統的關機延遲。</p><h4 id="看門狗問題" tabindex="-1">看門狗問題！ <a class="header-anchor" href="#看門狗問題" aria-label="Permalink to “看門狗問題！”">​</a></h4><p>Linux 有一個名為看門狗的模組，用於監控某些服務是否在運行。它可以被配置為在系統因軟件錯誤而掛起時自動重啓系統。</p><p>在桌面系統上使用看門狗是不常見的，因為你可以手動關閉或重啓系統。它經常被用於遠程服務器上。</p><p>首先檢查看門狗是否在運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ps -af | grep watch*</span></span></code></pre></div><p>如果你的系統正在運行看門狗，你可以在 systemd 配置文件 <code>/etc/systemd/system.conf</code> 中將 <code>ShutdownWatchdogSec</code> 的值從 10 分鐘改為更低的值。</p><h3 id="你能解決關機時間過長的問題嗎" tabindex="-1">你能解決關機時間過長的問題嗎？ <a class="header-anchor" href="#你能解決關機時間過長的問題嗎" aria-label="Permalink to “你能解決關機時間過長的問題嗎？”">​</a></h3><p>希望本教程能幫助你解決系統長時間關機的問題。如果你成功解決了這個問題，請在評論中告訴我。</p><hr>',32)),i("p",null,[s[13]||(s[13]=t("via: ",-1)),n(e,{href:"https://itsfoss.com/long-shutdown-linux/"},{default:o(()=>[...s[12]||(s[12]=[t("https://itsfoss.com/long-shutdown-linux/",-1)])]),_:1})]),i("p",null,[s[18]||(s[18]=t("作者：",-1)),n(e,{href:"https://itsfoss.com/author/abhishek/"},{default:o(()=>[...s[14]||(s[14]=[t("Abhishek Prakash",-1)])]),_:1}),s[19]||(s[19]=t(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:o(()=>[...s[15]||(s[15]=[t("lujun9972",-1)])]),_:1}),s[20]||(s[20]=t(" 譯者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:o(()=>[...s[16]||(s[16]=[t("geekpi",-1)])]),_:1}),s[21]||(s[21]=t(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:o(()=>[...s[17]||(s[17]=[t("wxy",-1)])]),_:1})]),i("p",null,[s[24]||(s[24]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[22]||(s[22]=[t("LCTT",-1)])]),_:1}),s[25]||(s[25]=t(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:o(()=>[...s[23]||(s[23]=[t("Linux中國",-1)])]),_:1}),s[26]||(s[26]=t(" 榮譽推出",-1))])])}const y=l(u,[["render",g]]);export{c as __pageData,y as default};
